{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6efe6;--card:#fff6ef;--muted:#7a6a5a;--accent:#8a5a3c;--accent-2:#c08b63;--glass:rgba(255,255,255,0.6);font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:var(--muted)}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(90deg,rgba(138,90,60,0.06),transparent)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:48px;height:48px;border-radius:12px;background:radial-gradient(circle at 30% 30%,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-size:15px}
    main{max-width:980px;margin:28px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:22px;align-items:start}
    .intro{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(122,106,90,0.06)}
    .intro h1{margin:0 0 8px 0;color:var(--accent)}
    .intro p{margin:0;color:var(--muted)}
    .details{background:var(--glass);padding:18px;border-radius:12px}
    .pricing-grid{display:flex;gap:14px;margin-top:18px}
    .plan{flex:1;background:#fff;padding:16px;border-radius:10px;border:1px solid rgba(138,90,60,0.06)}
    .plan h3{margin:0 0 6px 0;color:var(--accent)}
    .rate{font-size:20px;font-weight:700;color:var(--accent-2)}
    .plan p{margin:6px 0 12px 0;color:var(--muted)}
    .plan button{background:transparent;border:1px solid var(--accent);padding:8px 12px;border-radius:8px;color:var(--accent)}
    .note{font-size:13px;color:#7e6e5f;margin-top:10px}
    .planner{margin-top:22px;background:#fff;padding:16px;border-radius:12px;border:1px solid rgba(138,90,60,0.04)}
    .row{display:flex;gap:10px;margin-bottom:10px}
    label{font-size:13px;color:var(--muted)}
    select,input[type=text],textarea{width:100%;padding:8px;border-radius:8px;border:1px solid #e7dfd6;background:transparent}
    .goals{display:flex;gap:8px;flex-wrap:wrap}
    .chip{padding:6px 10px;border-radius:999px;border:1px solid rgba(138,90,60,0.12);background:#fff;font-size:13px;cursor:pointer}
    .chip.active{background:linear-gradient(90deg,var(--accent-2),var(--accent));color:#fff;border:1px solid transparent}
    .summary{margin-top:12px}
    textarea.summary-box{width:100%;height:120px;padding:12px;border-radius:10px;border:1px dashed rgba(122,106,90,0.08);font-family:monospace}
    .actions{display:flex;gap:8px;justify-content:flex-end;margin-top:8px}
    .btn{padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .btn.primary{background:var(--accent);color:#fff}
    .btn.ghost{background:transparent;border:1px solid rgba(138,90,60,0.12)}
    footer{max-width:980px;margin:18px auto;padding:18px;color:#6f6253;font-size:13px}
    .small{font-size:13px;color:#6f6253}
    /* decorative SVG pattern placeholder */
    .pattern{position:fixed;right:-120px;bottom:-120px;opacity:0.08;filter:grayscale(30%)}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">TP</div>
      <div>
        <div style="font-weight:600">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="about.html">Meet</a>
      <a href="specialties.html">Focus</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Investment</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <div class="intro">
        <h1>Care you can plan around</h1>
        <p>A practical guide to how sessions are offered and how I tailor time to the work you bring. If you prefer, we can shape a rhythm that fits your week and costs.</p>
        <div class="pricing-grid" aria-hidden="false">
          <div class="plan">
            <h3>Regular Sessions</h3>
            <div class="rate">$160 / session</div>
            <p>Weekly or every-other-week appointments for steady progress. Typical clients meet for 45–55 minutes.</p>
            <button onclick="selectPlan('Regular Sessions')">Choose</button>
          </div>
          <div class="plan">
            <h3>Focused Series</h3>
            <div class="rate">$880 / 6-session bundle</div>
            <p>A short, contained commitment to address a specific goal; sessions scheduled weekly or biweekly.</p>
            <button onclick="selectPlan('Focused Series')">Choose</button>
          </div>
          <div class="plan">
            <h3>Check-In</h3>
            <div class="rate">$90 / 20-min</div>
            <p>Brief follow-up or planning visits—useful between longer sessions or during busy periods.</p>
            <button onclick="selectPlan('Check-In')">Choose</button>
          </div>
        </div>
        <div class="note">Insurance: I am a private-pay practitioner. I can provide a receipt (superbill) you may submit to your insurer.</div>
      </div>
      <aside class="details">
        <strong style="color:var(--accent)">Session Planner</strong>
        <p style="margin:8px 0;color:var(--muted)">Build a simple plan that fits your needs and copy it to bring when you book.</p>
        <div class="planner" id="planner">
          <div class="row">
            <label for="goalInput">Primary intention</label>
            <input id="goalInput" type="text" placeholder="What would you like to focus on? e.g., managing overwhelm">
          </div>
          <div class="row">
            <label>Goals (tap to select)</label>
            <div class="goals" id="goalsList">
              <div class="chip" data-val="Coping skills">Coping skills</div>
              <div class="chip" data-val="Relationship work">Relationship work</div>
              <div class="chip" data-val="Mood tracking">Mood tracking</div>
              <div class="chip" data-val="Life transitions">Life transitions</div>
              <div class="chip" data-val="Behavior patterns">Behavior patterns</div>
            </div>
          </div>
          <div class="row">
            <div style="flex:1">
              <label for="frequency">Frequency</label>
              <select id="frequency">
                <option>Weekly</option>
                <option>Every other week</option>
                <option>Monthly</option>
                <option>Short series (6 sessions)</option>
              </select>
            </div>
            <div style="width:120px">
              <label for="length">Session length</label>
              <select id="length">
                <option>45 minutes</option>
                <option>50 minutes</option>
                <option>20 minutes</option>
              </select>
            </div>
          </div>
          <div class="row">
            <label for="notes">Notes for planning</label>
            <textarea id="notes" placeholder="Anything else to note: scheduling constraints, accessibility needs, questions for intake" rows="3"></textarea>
          </div>
          <div class="summary">
            <label for="summaryBox">Plan summary</label>
            <textarea id="summaryBox" class="summary-box" readonly aria-readonly="true">Your plan will appear here.</textarea>
            <div class="actions">
              <button class="btn ghost" id="previewBtn">Preview</button>
              <button class="btn primary" id="copyBtn">Copy plan</button>
            </div>
          </div>
        </div>
      </aside>
    </section>
    <section style="margin-top:22px;padding:16px;background:#fff;border-radius:10px;border:1px solid rgba(138,90,60,0.04)">
      <h3 style="margin-top:0;color:var(--accent)">Ways of paying and practical details</h3>
      <p class="small">Sessions are private-pay. I provide superbills for insurance reimbursement when appropriate. If finances are a barrier, we can discuss a limited sliding scale for a few spots. I do not accept insurance directly; any reduction is offered as a clinical accommodation and is not a guarantee.</p>
    </section>
  </main>
  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
      <div>
        <div style="font-weight:600">{{BUSINESS_NAME}}</div>
        <div class="small">Confidentiality: sessions are private and protected, with the limits required by law. I will discuss those limits with you at intake.</div>
      </div>
      <div style="text-align:right">
        <div class="small">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div class="small">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </div>
    <p class="small" style="margin-top:10px">Scope: I do not provide emergency/crisis services. If you are in immediate danger or need urgent help, call your local emergency number or crisis line.</p>
  </footer>

  <svg class="pattern" width="320" height="320" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <linearGradient id="g1" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="#c8a07a" stop-opacity="0.8"/>
        <stop offset="1" stop-color="#8a5a3c" stop-opacity="0.7"/>
      </linearGradient>
    </defs>
    <rect width="200" height="200" fill="url(#g1)" rx="16"/>
    <g fill="rgba(255,255,255,0.14)">
      <circle cx="40" cy="40" r="22"/>
      <circle cx="120" cy="80" r="14"/>
      <circle cx="70" cy="140" r="26"/>
    </g>
  </svg>

  <script>
    // Session Planner logic
    (function(){
      const chips = document.querySelectorAll('.chip');
      const summaryBox = document.getElementById('summaryBox');
      const copyBtn = document.getElementById('copyBtn');
      const previewBtn = document.getElementById('previewBtn');
      const goalInput = document.getElementById('goalInput');
      const frequency = document.getElementById('frequency');
      const length = document.getElementById('length');
      const notes = document.getElementById('notes');
      let selected = new Set();

      chips.forEach(c=>c.addEventListener('click',()=>{
        const v=c.dataset.val;
        if(selected.has(v)){selected.delete(v);c.classList.remove('active')}else{selected.add(v);c.classList.add('active')}
        renderSummary();
      }));

      [goalInput,frequency,length,notes].forEach(el=>el.addEventListener('input',renderSummary));
      previewBtn.addEventListener('click',renderSummary);
      copyBtn.addEventListener('click',async ()=>{
        try{
          await navigator.clipboard.writeText(summaryBox.value || '');
          copyBtn.textContent='Copied';
          setTimeout(()=>copyBtn.textContent='Copy plan',1400);
        }catch(e){alert('Copy failed — select and copy manually.')}
      });

      window.selectPlan = function(planName){
        notes.value = 'Preferred plan: '+planName;
        renderSummary();
        window.scrollTo({top:0,behavior:'smooth'});
      }

      function renderSummary(){
        const goalText = goalInput.value.trim();
        const goals = Array.from(selected).join(', ');
        const pieces = [];
        if(goalText) pieces.push('Primary intention: '+goalText);
        if(goals) pieces.push('Selected goals: '+goals);
        pieces.push('Frequency: '+frequency.value);
        pieces.push('Session length: '+length.value);
        if(notes.value.trim()) pieces.push('Notes: '+notes.value.trim());
        pieces.push('\nPrepared for: {{BUSINESS_NAME}} — bring this when you book.');
        pieces.push('Contact: {{EMAIL}} | {{PHONE}}');
        summaryBox.value = pieces.join('\n');
      }

      // initial render
      renderSummary();
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Questions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f3ee;--muted:#6f6253;--accent:#8a5a3c;--card:#fff;--glass:rgba(255,255,255,0.7)}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;margin:0;background:var(--bg);color:var(--muted)}
    header{padding:18px 28px;display:flex;justify-content:space-between;align-items:center}
    header .logo{background:linear-gradient(180deg,#b88666,#8a5a3c);width:46px;height:46px;border-radius:10px;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:16px;text-decoration:none;color:var(--muted)}
    main{max-width:900px;margin:20px auto;padding:18px}
    .lead{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(138,90,60,0.05)}
    .lead h2{margin:0;color:var(--accent)}
    .faq-list{margin-top:16px}
    .q{background:#fff;padding:12px;border-radius:10px;margin-bottom:8px;border:1px solid rgba(122,106,90,0.04)}
    .q button{all:unset;cursor:pointer;display:flex;justify-content:space-between;width:100%;align-items:center}
    .a{margin-top:8px;color:#5f5346;font-size:14px}
    .wizard{margin-top:18px;background:var(--card);padding:12px;border-radius:10px}
    .steps{display:flex;gap:8px;margin-bottom:12px}
    .step{padding:6px 10px;border-radius:8px;background:rgba(138,90,60,0.06);font-size:13px}
    input[type=radio]{margin-right:8px}
    .results{white-space:pre-wrap;background:#fbf7f2;padding:12px;border-radius:8px;border:1px dashed rgba(138,90,60,0.06);font-family:monospace}
    .btn{padding:8px 12px;border-radius:8px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    footer{max-width:900px;margin:18px auto;padding:12px;color:#6f6253;font-size:13px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">TP</div>
      <div style="font-weight:600">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Meet</a>
      <a href="fees.html">Investment</a>
      <a href="book.html">Schedule</a>
    </nav>
  </header>
  <main>
    <section class="lead">
      <h2>Questions people commonly ask</h2>
      <p style="margin:8px 0;color:var(--muted)">Short, clear answers to help you decide whether to reach out. If something feels unclear, we can go over it at a first meeting.</p>
    </section>

    <section class="faq-list" aria-live="polite">
      <div class="q">
        <button aria-expanded="false" onclick="toggle(this)">
          <span>How long does it take to notice change?</span>
          <span aria-hidden="true">▸</span>
        </button>
        <div class="a" hidden>Change shows up differently for each person. Some notice shifts in weeks, others over months. We focus on small, practical steps you can use between sessions.</div>
      </div>
      <div class="q">
        <button aria-expanded="false" onclick="toggle(this)">
          <span>Do you offer remote sessions?</span>
          <span aria-hidden="true">▸</span>
        </button>
        <div class="a" hidden>I offer secure video sessions and in-person appointments by arrangement. We will choose what feels most effective and doable for you.</div>
      </div>
      <div class="q">
        <button aria-expanded="false" onclick="toggle(this)">
          <span>Do you accept insurance?</span>
          <span aria-hidden="true">▸</span>
        </button>
        <div class="a" hidden>I operate privately and can provide a superbill you may submit to your insurance if they reimburse out-of-network providers.</div>
      </div>
    </section>

    <section class="wizard">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <strong style="color:var(--accent)">Self-screening intake</strong>
          <div style="color:var(--muted);font-size:14px">A short, non-diagnostic set of prompts to help you gather what to bring to a first conversation.</div>
        </div>
        <div>
          <button class="btn" id="resetWizard">Reset</button>
        </div>
      </div>

      <div class="steps" aria-hidden="false" style="margin-top:10px">
        <div class="step">1 • Where you are</div>
        <div class="step">2 • What helps</div>
        <div class="step">3 • Practicalities</div>
      </div>

      <form id="wizardForm">
        <div style="margin-bottom:10px">
          <label>Which of these best describes what brings you here?</label>
          <div style="margin-top:6px">
            <label><input type="radio" name="presenting" value="Stress or overwhelm"> Stress or overwhelm</label><br>
            <label><input type="radio" name="presenting" value="Low mood or sadness"> Low mood or sadness</label><br>
            <label><input type="radio" name="presenting" value="Relationship concerns"> Relationship concerns</label><br>
            <label><input type="radio" name="presenting" value="Transitions or decisions"> Transitions or decisions</label>
          </div>
        </div>

        <div style="margin-bottom:10px">
          <label>What currently helps you cope? (check any)</label>
          <div style="margin-top:6px">
            <label><input type="checkbox" name="coping" value="Talking with friends/family"> Talking with friends/family</label><br>
            <label><input type="checkbox" name="coping" value="Exercise or movement"> Exercise or movement</label><br>
            <label><input type="checkbox" name="coping" value="Journaling or expressive writing"> Journaling or expressive writing</label><br>
            <label><input type="checkbox" name="coping" value="Medication or medical care"> Medication or medical care</label>
          </div>
        </div>

        <div style="margin-bottom:10px">
          <label>Practical considerations</label>
          <select id="availability" name="availability">
            <option>Weekday mornings</option>
            <option>Weekday evenings</option>
            <option>Weekend availability</option>
          </select>
        </div>

        <div style="display:flex;gap:8px;justify-content:flex-end">
          <button type="button" class="btn" id="generate">Create notes</button>
        </div>
      </form>

      <div style="margin-top:12px">
        <label style="font-weight:600">Notes to bring to intake</label>
        <div id="result" class="results">Use the form above to assemble a short set of points to share in a first meeting.</div>
        <div style="display:flex;justify-content:flex-end;margin-top:8px;gap:8px">
          <button class="btn" id="copyNotes">Copy</button>
        </div>
      </div>

    </section>
  </main>
  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div style="max-width:70%">Confidentiality and boundaries: Conversations are confidential within limits required by law. This screening does not replace clinical assessment. If you are in crisis, call emergency services or a crisis line.</div>
      <div style="text-align:right">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script>
    function toggle(btn){
      const expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !expanded);
      const ans = btn.parentElement.querySelector('.a');
      if(ans) ans.hidden = expanded;
    }

    // Wizard logic
    (function(){
      const form = document.getElementById('wizardForm');
      const generate = document.getElementById('generate');
      const result = document.getElementById('result');
      const copyNotes = document.getElementById('copyNotes');
      const reset = document.getElementById('resetWizard');

      function collect(){
        const data = new FormData(form);
        const presenting = data.get('presenting') || 'Not selected';
        const coping = data.getAll('coping');
        const availability = data.get('availability');
        const lines = [];
        lines.push('Presenting concern: '+presenting);
        if(coping.length) lines.push('Current supports: '+coping.join(', ')); else lines.push('Current supports: None listed');
        lines.push('Availability: '+availability);
        lines.push('\nQuestions to bring to consultation:');
        lines.push('- What short-term steps might help with the presenting concern?');
        lines.push('- How do I track shifts between sessions?');
        lines.push('- Are there simple skills I can practice at home?');
        lines.push('\nPrepared for: {{BUSINESS_NAME}}');
        return lines.join('\n');
      }

      generate.addEventListener('click',()=>{ result.textContent = collect(); });
      copyNotes.addEventListener('click',async ()=>{
        try{ await navigator.clipboard.writeText(result.textContent); copyNotes.textContent='Copied'; setTimeout(()=>copyNotes.textContent='Copy',1200);}catch(e){alert('Copy failed.')}
      });
      reset.addEventListener('click',()=>{ form.reset(); result.textContent='Use the form above to assemble a short set of points to share in a first meeting.'});
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Schedule — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f4efe8;--muted:#6b5d4f;--accent:#8a5a3c;--card:#fff}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;margin:0;background:var(--bg);color:var(--muted)}
    header{display:flex;justify-content:space-between;padding:16px 22px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(180deg,#b08968,#8a5a3c);color:#fff;display:flex;align-items:center;justify-content:center}
    nav a{margin-left:12px;text-decoration:none;color:var(--muted)}
    main{max-width:820px;margin:18px auto;padding:18px}
    .card{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(138,90,60,0.04)}
    label{display:block;font-size:13px;margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e8e0d6;background:transparent}
    .cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}
    .btn{padding:10px 12px;border-radius:10px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    .secondary{background:transparent;border:1px solid rgba(138,90,60,0.08);color:var(--muted)}
    .small{font-size:13px;color:#6f6253}
    .intake{margin-top:14px}
    .summary{white-space:pre-wrap;background:#fbf8f4;padding:12px;border-radius:8px;font-family:monospace;border:1px dashed rgba(138,90,60,0.05)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">TP</div>
      <div style="font-weight:600">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Investment</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <section class="card">
      <h2 style="margin-top:0;color:var(--accent)">Request an appointment</h2>
      <p class="small">Complete the form below and I will follow up to confirm timing. This is not an emergency contact.</p>

      <form id="bookingForm" onsubmit="return false;">
        <div class="cols">
          <div>
            <label for="name">Your name</label>
            <input id="name" name="name" required>
          </div>
          <div>
            <label for="email">Email</label>
            <input id="email" name="email" type="email" required>
          </div>
        </div>

        <div style="margin-top:10px">
          <label for="phone">Phone (optional)</label>
          <input id="phone" name="phone" placeholder="{{PHONE}}">
        </div>

        <div style="margin-top:10px">
          <label for="service">Type of session</label>
          <select id="service" name="service">
            <option>Initial consultation (50 min)</option>
            <option>Regular session (45–50 min)</option>
            <option>Brief check-in (20 min)</option>
          </select>
        </div>

        <div style="margin-top:10px">
          <label for="when">Preferred days/times</label>
          <input id="when" name="when" placeholder="e.g., Tuesdays after 5pm">
        </div>

        <div style="margin-top:12px">
          <label>Notes or questions for intake</label>
          <textarea id="bookingNotes" rows="4" placeholder="Anything important: accessibility, concerns, what you'd like from therapy"></textarea>
        </div>

        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px">
          <div class="small">By submitting, you agree to be contacted to schedule. I will discuss confidentiality and limits at intake.</div>
          <div style="display:flex;gap:8px">
            <button class="btn" id="submitBtn">Send request</button>
            <button class="btn secondary" id="fillWizard" type="button">Use intake helper</button>
          </div>
        </div>
      </form>

      <div class="intake">
        <strong style="color:var(--accent)">Intake helper</strong>
        <p class="small">A short self-check that produces a text you can paste into the notes above or copy to share at our first meeting.</p>

        <div style="display:flex;gap:8px;margin-bottom:8px">
          <input id="mood" placeholder="Briefly: what's the main concern?">
          <select id="priority">
            <option>Stabilize day-to-day</option>
            <option>Work on a specific problem</option>
            <option>Longer-term therapy</option>
          </select>
        </div>

        <div style="display:flex;gap:8px">
          <button class="btn" id="makeSummary">Make summary</button>
          <button class="btn secondary" id="copySummary">Copy</button>
        </div>

        <div style="margin-top:10px">
          <label>Summary</label>
          <div id="summary" class="summary">Use the helper to craft a short summary for intake.</div>
        </div>
      </div>

    </section>

    <section style="margin-top:14px" class="card">
      <h4 style="margin:0;color:var(--accent)">After you request</h4>
      <p class="small">I will reply by email within a few business days to confirm availability and offer next steps. If you need immediate support, please contact local emergency services or a crisis line.</p>
    </section>
  </main>

  <footer style="max-width:820px;margin:12px auto;padding:12px;color:#6f6253;font-size:13px">
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>Confidentiality: sessions are private with legally defined limits. We will review specifics before we begin.</div>
      <div>Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script>
    // Booking form simulation
    (function(){
      const submitBtn = document.getElementById('submitBtn');
      const form = document.getElementById('bookingForm');
      submitBtn.addEventListener('click',()=>{
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        if(!name || !email){ alert('Please provide name and email.'); return; }
        submitBtn.textContent='Sent';
        setTimeout(()=>submitBtn.textContent='Send request',2000);
        alert('Request noted. I will be in touch to confirm a time.');
        form.reset();
      });

      // Intake helper
      const makeSummary = document.getElementById('makeSummary');
      const copySummary = document.getElementById('copySummary');
      const summary = document.getElementById('summary');
      const fillWizard = document.getElementById('fillWizard');

      makeSummary.addEventListener('click',()=>{
        const mood = document.getElementById('mood').value.trim() || 'Not specified';
        const priority = document.getElementById('priority').value;
        const s = [];
        s.push('Presenting: '+mood);
        s.push('Priority: '+priority);
        s.push('Availability: '+(document.getElementById('when') ? document.getElementById('when').value.trim() || 'Not listed' : 'Not listed'));
        s.push('Brief supports: '+(document.getElementById('phone').value.trim() || 'None listed'));
        s.push('\nPrepared to discuss goals and next steps with {{BUSINESS_NAME}}.');
        summary.textContent = s.join('\n');
      });

      copySummary.addEventListener('click',async ()=>{
        try{ await navigator.clipboard.writeText(summary.textContent); copySummary.textContent='Copied'; setTimeout(()=>copySummary.textContent='Copy',1200);}catch(e){alert('Copy failed.');}
      });

      fillWizard.addEventListener('click',()=>{
        // open a small intake dialog simulated by prompting
        const concise = prompt('If you like, paste a one-line summary for notes:');
        if(concise !== null){ document.getElementById('bookingNotes').value = concise; }
      });
    })();
  </script>
</body>
